#!/usr/bin/env python3
"""Typed capture records and revision-aware publication reconciliation.

A record identity is ``(type, id)`` and is global across captures.  At a query
time only rows with ``published <= query`` exist; the highest visible revision
wins, identical semantic contents at that revision collapse to one record and
two or more distinct contents make the identity conflicted (never live).
"""
from common import (Invalid, MAX_ATTEMPT, MAX_PAYLOAD, MAX_REVISION, MAX_TIME,
                    address, decimal, decode64, ident)

ICMP_RESULT = {'echo': 0, 'error': 1, 'timeout': 2}
APP_RESULT = {'open': 0, 'closed': 1, 'timeout': 2}
EMPTY_TAIL = ('',) * 9

# detail layouts (a live record's canonical, spell-free description)
#   icmp: (0, lease, event, target, responder|-1, result, is_canary)
#   app : (1, lease, event, target, service, attempt, result, payload bytes)
#   tomb: (2,)


def parse_record(values, context, probes):
    """Validate one logical CSV record; raise Invalid for a record failure.

    Returns ``(identity, revision, published, content, detail)`` where equal
    ``content`` values mean equal semantic contents at that revision.
    """
    if len(values) != 14:
        raise Invalid('wrong field count')
    kind, name, revision, published, op, lease, event, probe, target = values[:9]
    responder, result, service, attempt, payload = values[9:]

    if kind == 'icmp':
        code = 0
    elif kind == 'app':
        code = 1
    else:
        raise Invalid('unknown record type')
    if ident(name) is False:
        raise Invalid('bad record id')
    rev = decimal(revision, MAX_REVISION)
    pub = decimal(published, MAX_TIME)

    if op == 'delete':
        if tuple(values[5:]) != EMPTY_TAIL:
            raise Invalid('delete tail must be empty')
        return ((code, name), rev, pub, ('d',), (2,))
    if op != 'put':
        raise Invalid('unknown op')

    leases = context['leases']
    row = leases.get(lease)
    if row is None:
        raise Invalid('unknown lease')
    ev = decimal(event, MAX_TIME)
    if ev < row['start'] or ev >= row['end'] or ev > pub:
        raise Invalid('event outside lease or after publication')
    aim = address(target)

    if code == 0:
        table = probes.get(lease)
        planned = table.get(probe) if table is not None else None
        if planned is None:
            raise Invalid('probe not in lease manifest')
        if aim != planned[0]:
            raise Invalid('target differs from planned probe target')
        state = ICMP_RESULT.get(result)
        if state is None:
            raise Invalid('unknown icmp result')
        if state == 2:
            if responder != '':
                raise Invalid('timeout responder must be empty')
            reply = -1
        else:
            reply = address(responder)
        if service != '' or attempt != '' or payload != '':
            raise Invalid('icmp service/attempt/payload must be empty')
        content = ('i', lease, ev, probe, aim, reply, state)
        detail = (0, lease, ev, aim, reply, state, planned[1])
    else:
        services = context['services']
        kind_of = services.get(service)
        if kind_of is None:
            raise Invalid('unknown service')
        if probe != '' or responder != '':
            raise Invalid('application probe/responder must be empty')
        state = APP_RESULT.get(result)
        if state is None:
            raise Invalid('unknown application result')
        tries = decimal(attempt, MAX_ATTEMPT)
        data = decode64(payload)
        if len(data) > MAX_PAYLOAD:
            raise Invalid('payload too large')
        if data != b'' and (state != 0 or kind_of == 'tcp'):
            raise Invalid('payload must be empty')
        content = ('a', lease, ev, aim, service, tries, state, data)
        detail = (1, lease, ev, aim, service, tries, state, data)
    return ((code, name), rev, pub, content, detail)


class Ledger:
    """Revision index over every valid record, queryable at each snapshot."""

    __slots__ = ('identities', 'details')

    def __init__(self, records):
        details = {}
        tree = {}
        for identity, revision, published, content, detail in records:
            revisions = tree.get(identity)
            if revisions is None:
                revisions = tree[identity] = {}
            previous = revisions.get(revision)
            if previous is None:
                previous = revisions[revision] = {}
            old = previous.get(content)
            if old is None or published < old:
                previous[content] = published
            if content not in details:
                details[content] = detail
        # Sort each identity's revisions downward so a query scan stops early.
        self.identities = []
        for identity, revisions in tree.items():
            ordered = []
            for revision in sorted(revisions, reverse=True):
                contents = revisions[revision]
                earliest = min(contents.values())
                ordered.append((revision, earliest, contents))
            self.identities.append((identity, ordered))
        self.details = details

    def at(self, moment):
        """Return (counts, live details) visible at the given query time."""
        live = []
        deleted = conflicts = 0
        details = self.details
        for _, ordered in self.identities:
            for revision, earliest, contents in ordered:
                if earliest <= moment:
                    if len(contents) > 1:
                        # Multiple spellings of one semantic content already
                        # collapsed; two distinct contents conflict forever.
                        visible = 0
                        for content, published in contents.items():
                            if published <= moment:
                                visible += 1
                                if visible > 1:
                                    break
                        if visible > 1:
                            conflicts += 1
                        elif visible == 1:
                            # Only one content is published yet: treat as live.
                            content = next(c for c, p in contents.items()
                                           if p <= moment)
                            detail = details[content]
                            if detail[0] == 2:
                                deleted += 1
                            else:
                                live.append(detail)
                        else:
                            deleted += 0
                    else:
                        detail = details[next(iter(contents))]
                        if detail[0] == 2:
                            deleted += 1
                        else:
                            live.append(detail)
                    break
        return {'live': len(live), 'deleted': deleted, 'conflict': conflicts}, live
